-- GENERATED by `wfj generate` from data/gossip/gossip-42.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["420a67d019499bb2"] = { "Fatto, fatto e fatto.", "." },
  ["420be9190bd01824"] = { "Intrusi nella Manifattura? I miei costrutti vi distruggeranno!", "." },
  ["4211f69cf9a9f054"] = { "Ho abbastanza ingredienti per una sapta del fuoco, se trovi la borsa dei reagenti e un po' di catrame di fuoco. I fanatici delle ⟦Burning Blade=Lame Ardenti⟧ tengono in quelle borse i componenti giusti per la maggior parte dei loro incantesimi, e di solito hanno abbastanza degli oggetti che mi servono da non doverci spingere molto oltre per cercare altro.\n\nLe sapta si fanno sempre con ingredienti strettamente legati ai rispettivi elementi. Il legame degli stregoni con il fuoco ci rende il lavoro più facile.", "." },
  ["422b323d819d2839"] = { "Sei mort<o/a>, non sepolt<o/a>. Ora fammi vedere il tuo meglio!", "." },
  ["423347d4ad608970"] = { "Forza, servimi!", "." },
  ["423d0270a2049a4d"] = { "I resti sono coperti di mosche e vermi.", "." },
  ["42401836ae57aa61"] = { "Dobbiamo garantire la sopravvivenza di questo accampamento a ogni costo, {class}! Ai nostri nemici non va concessa alcuna pietà, perché di certo loro non ne avrebbero per noi, se ne avessimo bisogno.", "." },
  ["42440e1a999c70c7"] = { "Il primo è un pegno primordiale che va preso al più potente dei luogotenenti degli Hakkari: Jin'do e il Signore del Sangue.\n\nIl secondo è una Bambola Vudù con Spilloni. Si trovano tra i cumuli di rifiuti che ingombrano questo luogo immondo. Cerca dentro i Jinxed Hoodoo Pile.\n\nPortami queste cose e creerò per te un incantamento potente!", "." },
  ["424713c980e460e8"] = { "Oh, è così orribile, <signore/signorina>. Casa Barov un tempo era piena di vita... piena di splendore. Il maniero era la residenza principale dei Barov, al centro del loro vasto impero.\n\nIo e Lucien notammo che, con il passare dei giorni, i Barov diventavano sempre più cupi. Abbattuti. La paranoia e la rabbia spesso sopraffacevano il padrone e la padrona. Di notte sentivamo i Barov litigare nelle loro stanze. Da quel che capimmo, la loro avidità aveva «rotto la diga», per così dire.", "." },
  ["424859d8fad328a9"] = { "Un ⟦Alliance Commendation Signet=Anello d'Encomio dell'Alleanza⟧ viene conferito a <un/una> <eroe/eroina> che va ben oltre il proprio dovere verso l'⟦Alliance=Alleanza⟧. In tutte le capitali si trovano vari ufficiali dell'encomio per le fazioni dell'⟦Alliance=Alleanza⟧: parla con quello della fazione con cui vuoi aumentare la reputazione, e dagli il numero di anelli che ti chiede!\n\nA proposito, durante lo sforzo bellico qui, se per i tuoi anelli preferisci una ricompensa materiale invece della reputazione, cerca il primo maresciallo Nevealta.", "." },
  ["425ba620a07ef2b1"] = { "Il Liquore dell'Invisibilità è pronto per te, {name}.", "." },
  ["425c8d8abde775d4"] = { "⟦Tower Point=Torre Granguardia⟧ controlla il passo tra il ⟦Field of Strife=Pian della Discordia⟧ e i territori dell'⟦Horde=Orda⟧ a sud.\n\nNon è in mano a nessuna delle due parti.", "." },
  ["4260fded613356fe"] = { "Alcuni mi chiamano... Impsy?", "." },
  ["4262b2a692a56b75"] = { "Quella magia porta solo guai, te lo dico io. Non so perché abbiano permesso a quel Grimrizz di sistemarsi fuori dalla ⟦Thunderbrew Distillery=Distilleria Birratuono⟧, fra tutti i posti! Stagli alla larga, hai capito?", "." },
  ["4267c7abd181b092"] = { "Turno di guardia, odio i turni di guardia.", "." },
  ["426cc0265910ef23"] = { "Questo è il campo di battaglia della ⟦Alterac Valley=Valle d'Alterac⟧. Entrambe le parti stanno ancora combattendo.", "." },
  ["426d4804095306c7"] = { "Althea, ci sono voci di strani avvenimenti al cimitero. Ello crede che sia il presagio di un attacco a ⟦Darkshire=Borgoscuro⟧.", "." },
  ["42743e008f453ad5"] = { "Non mostrate pietà a questi selvaggi, soldati! Loro non ne avranno per voi!", "." },
  ["427609bc26578b8e"] = { "⟦Davil Lightfire=Davil Fiocafiamma⟧ è stato sconfitto! Il ⟦Darrowshire=Borgo di Darrow⟧ è perduto!", "." },
  ["42778da898ec6614"] = { "Ehi, mon, tu sei qui per portarmi barre di mithril, di sicuro. Ci sono grossi guai in arrivo nel deserto di ⟦Silithus=Silitus⟧, ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Noi e l'⟦Alliance=Alleanza⟧ stavolta facciamo di tutto per fermare quegli insetti, ed è per questo che vedi tutti qui.\n\nL'⟦Horde=Orda⟧ mi chiede di raccogliere $2009w per lo sforzo bellico, ma io ne ho solo $2008w. Allora mi aiuti o no?", "." },
  ["427cc287e7272380"] = { "Vai dritto nella zona nord-ovest della ⟦Valley of Honor=Valle dell'Onore⟧. Lì troverai la Hunter's Hall.", "." },
  ["427d0b771c074797"] = { "Ecco a te, {name}. Ora ti darò il potere di addomesticare una bestia, e di richiamarla e congedarla come ti pare.\n\nTrovati un famiglio buono e leale, e goditi la caccia!", "." },
  ["42a354f3ad27d654"] = { "%s entra in una furia berserker!", "." },
  ["42a41b5d749d499a"] = { "Hai ragni o scarafaggi, {class}? Corrono veloci, ma se tu sei più veloce scoprirai che sono una vera prelibatezza!", "." },
  ["42a709aa5e9109ab"] = { "<Non riesci a capire niente del gergo tecnico di questa pergamena.>", "." },
  ["42b1665f791a6fa9"] = { "Se non dovessi restare qui giorno dopo giorno, avrei raggiunto la maestria necessaria per addestrare quelli come te! Purtroppo non è così. Va' a parlare con Hgarth al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.", "." },
  ["42b230311a77cf8f"] = { "Scatenate la furia e che sia fatta!", "." },
  ["42b6bf68ac695212"] = { "Quella notte mi si sono rotte tutte e due le gambe. Come potrei dimenticarlo?", "." },
  ["42b8e30d9e124942"] = { "⟦Anachronos=Anacronos⟧, questo diversivo darà a te e al giovane druido il tempo di sigillare il cancello. Non esitare. Ora vediamo come se la cavano con la magia del caos.", "." },
  ["42b9563da3718ea6"] = { "Col tempo potrai imparare da me... ma non ancora! Perché non cominci parlando con ⟦Sprite Jumpsprocket=Sprite Giramolla⟧, qui alla mia destra? Torna da me quando avrai fatto un po' di pratica!", "." },
  ["42bf1a6ecff2fa5f"] = { "Non avresti aiutato la legione dei ⟦Blackrock=Roccianera⟧ se ti avessimo semplicemente chiesto il tuo aiuto, vero?", "." },
  ["42c0ad39c4726986"] = { "Puoi ritirare le tue lettere d'amore fuori dalla banca, al centro della ⟦Valley of Strength=Valle della Forza⟧.", "." },
  ["42c3073d7da4de10"] = { "Accidenti! Ho {name} addosso!", "." },
  ["42c30839a2d62735"] = { "Eccellente, è arrivato sangue fresco.", "." },
  ["42c9f128c22b6497"] = { "%s abbaia in attesa.", "." },
  ["42d26eac95bff2ef"] = { "Se lo chiedi a me, non c'è professione migliore di quella del minatore. E se lo chiedi a me, non c'è minatore migliore di un nano!", "." },
  ["42d9d588495e7752"] = { "<Prendi la lettera>", "." },
  ["42dbbaa327dd295b"] = { "Le nostre unità veterane stanno lasciando il campo. Ci servono altri rifornimenti!", "." },
  ["42e020d6290dab33"] = { "Polvere alla polvere.", "." },
  ["42e2e75d074272fb"] = { "Alegorn è un cuoco magistrale che ha avuto secoli per perfezionare la sua cucina. Dovresti considerarti fortunat<o/a> se decidesse di insegnarti. Se credi di esserne degn<o/a>, lo trovi alla ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧.", "." },
  ["42f4082db3f9c5f5"] = { "Se vuoi trovare Grumnus, la prima cosa da fare è andare a ⟦Ironforge=Forgiardente⟧. Vai proprio al centro della città e cerca la ⟦Great Forge=Grande Forgia⟧: dovresti trovarlo lì.", "." },
  ["42feba209f5bed91"] = { "Questo ponte avrebbe già dovuto essere distrutto. Quanto ci mettono quei pelandroni ad arrivare qui dagli Altopiani!", "." },
})
